import java.util.Scanner;

public class Main {
    static long num_x, num_y, max_n;
    static double min_diff_value = 1e9;
    static long final_num, final_den;

    static long gcd(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    static long lcm(long a, long b) {
        return a * b / gcd(a, b);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        num_x = sc.nextLong();
        num_y = sc.nextLong();
        max_n = sc.nextLong();

        if (num_y <= max_n) {
            while (gcd(num_x, num_y) > 1) {
                long g = gcd(num_x, num_y);
                num_x /= g;
                num_y /= g;
            }
            System.out.println(num_x + "/" + num_y);
            sc.close();
            return;
        }

        for (long i = 1; i <= max_n; i++) {
            long l = lcm(i, num_y);
            long w = num_x * (l / num_y);
            double diff1 = (double) (w - ((w / (l / i)) * (l / i))) / (double) l;
            if (min_diff_value > diff1) {
                min_diff_value = diff1;
                final_num = (w / (l / i));
                final_den = i;
            }
            long numerator = w + (l / i) - 1;
            long denominator = (l / i);
